#include <iostream>
#include <string>
using namespace std;

int main() {
    string a[4];

    while (cin >> a[0] >> a[1] >> a[2] >> a[3]) {
        bool found = false;

        for (int i = 0; i < 3 && !found; ++i) {
            for (int j = 0; j < 3; ++j) {
                int count = 0;
                count += (a[i][j] == '#');
                count += (a[i][j + 1] == '#');
                count += (a[i + 1][j] == '#');
                count += (a[i + 1][j + 1] == '#');

                if (count != 2) {
                    found = true;
                    break;
                }
            }
        }

        cout << (found ? "YES" : "NO") << '\n';
    }

    return 0;
}

